package com.sami.app.sales.receipt; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import com.sami.app.common.api.ApiResponse; import java.math.BigDecimal; import java.util.Map;
@RestController @RequestMapping("/api/v1/sales-receipts") @RequiredArgsConstructor public class SalesReceiptController { private final SalesReceiptService service; @PostMapping public ApiResponse<Map<String,Object>> create(@RequestParam Long companyId,@RequestParam Long branchId,@RequestParam Long customerId,@RequestParam BigDecimal amount,@RequestParam String paymentMethod,@RequestParam(required=false) String reference,@RequestHeader("Idempotency-Key") String key){return ApiResponse.ok(service.create(companyId,branchId,customerId,amount,paymentMethod,reference,key));} @PostMapping("/{id}/confirm") public ApiResponse<Map<String,Object>> confirm(@PathVariable Long id){return ApiResponse.ok(service.confirm(id));} }
